// Generated files under `.boundaries/generated/`, and their freshness check.
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { toDepcruiseRules } from './checks/depcruise-rules.js';
import { buildIndex, INDEX_PATH } from './index-file.js';
import { loadProject } from './manifest.js';

/** @typedef {import('./types.js').Project} Project */

export const DEPCRUISE_PATH = '.boundaries/generated/depcruise.cjs';

/**
 * Content of depcruise.cjs, or null when no Node component declares imports.
 * @param {Project} project
 * @returns {string | null}
 */
export function buildDepcruise(project) {
  const rules = project.manifests.filter((m) => m.component.language === 'node').flatMap(toDepcruiseRules);
  if (rules.length === 0) return null;
  return [
    '// Generated by agent-terminus from .boundaries/*.toml. Do not edit; run `boundaries generate`.',
    '// Optional: spread these rules into your own .dependency-cruiser.cjs `forbidden` list.',
    `module.exports = { forbidden: ${JSON.stringify(rules, null, 2)} };`,
    '',
  ].join('\n');
}

/**
 * Expected generated files (null content means the file must not exist).
 * @param {Project} project
 * @returns {{ file: string, content: string | null }[]}
 */
export function expectedFiles(project) {
  return [
    { file: INDEX_PATH, content: buildIndex(project) },
    { file: DEPCRUISE_PATH, content: buildDepcruise(project) },
  ];
}

/** @param {string} abs */
function readOrNull(abs) {
  return existsSync(abs) ? readFileSync(abs, 'utf8').replace(/\r\n/g, '\n') : null;
}

/**
 * Compares (and with `write`, rewrites) the generated files.
 * @param {{ project: Project, write: boolean }} options
 * @returns {{ file: string, stale: boolean }[]}
 */
export function generateFiles({ project, write }) {
  return expectedFiles(project).map(({ file, content }) => {
    const abs = path.join(project.root, file);
    const stale = readOrNull(abs) !== content;
    if (stale && write) {
      if (content === null) rmSync(abs, { force: true });
      else {
        mkdirSync(path.dirname(abs), { recursive: true });
        writeFileSync(abs, content);
      }
    }
    return { file, stale };
  });
}

/**
 * Loads the project and compares or writes its generated files.
 * Throws when the project has config errors.
 * @param {{ root: string, write: boolean }} options
 * @returns {Promise<{ file: string, stale: boolean }[]>}
 */
export async function generate({ root, write }) {
  const project = await loadProject(root);
  if (project.problems.length > 0) {
    throw new Error(`cannot generate: ${project.problems.length} config error(s); run boundaries validate`);
  }
  return generateFiles({ project, write });
}
